// Function to scale menu on window resize
function scale(x) {
    const menuToggle = document.getElementById("menu-toggle");
    const lightboxes = document.querySelectorAll("[id^='Lightbox_']");

    // Check if any lightbox is currently open (display: flex)
    const anyLightboxOpen = Array.from(lightboxes).some(
        (lightbox) => window.getComputedStyle(lightbox).display === "flex"
    );

    if (x.matches && !anyLightboxOpen) {
        // Only show menu-toggle if no lightbox is open
        menuToggle.style.display = "flex";
    } else {
        menuToggle.style.display = "none";
    }
}

// Media query listener setup
var x = window.matchMedia("(max-width: 1000px)");
scale(x); // Call listener function at runtime
x.addEventListener("change", () => scale(x)); // Attach listener function on state changes

// Declare constants in the global scope
const mouseTarget = document.getElementById("mouseTarget");
const rowId = document.getElementById("rowid");
const footer = document.querySelector("footer");
const socialElements = document.getElementById("social_elements2");

// Function to open the lightbox
// Function to open the lightbox
function openLightbox(lightboxId) {
    console.log("Opening lightbox with id:", lightboxId);
    loadMedia(lightboxId);

    // Store the current scroll position before opening the lightbox
    sessionStorage.setItem("scrollPosition", window.scrollY);

    // Hide all lightboxes except the one we are opening
    document.querySelectorAll("[id^='Lightbox_']").forEach(lightbox => {
        if (lightbox.id !== `Lightbox_${lightboxId}`) {
            lightbox.style.display = "none";
        }
    });

    // Apply styles to elements for opening the lightbox
    const lightbox = document.getElementById(`Lightbox_${lightboxId}`);
    const projectTitle = document.getElementById(`projecttitle_${lightboxId}`);

    lightbox.style.display = "flex";
    projectTitle.style.display = "block";
    mouseTarget.style.display = "none";
    rowId.style.display = "none";
    footer.style.display = "none";
    socialElements.style.display = "none";

    document.body.style.overflow = "hidden";

    // Set up the keys for navigating slides
    setKeys(lightboxId);

    // Retrieve the last slide index from sessionStorage
    const lastSlide = sessionStorage.getItem(`lastSlide_${lightboxId}`);
    if (lastSlide) {
        toSlide(lightboxId, parseInt(lastSlide)); // Go to the last known slide
    } else {
        toSlide(lightboxId, 1); // If no last slide, start from the first
    }
}

// Function to close the lightbox
function closeLightbox(lightboxId) {
    // Store elements locally in the function, still using global constants
    const lightbox = document.getElementById(`Lightbox_${lightboxId}`);
    const projectTitle = document.getElementById(`projecttitle_${lightboxId}`);

    // Reset styles to their default values for closing the lightbox
    lightbox.style.display = "none";
    projectTitle.style.display = "none";
    mouseTarget.style.display = "flex";
    rowId.style.display = "grid";
    footer.style.display = "flex";
    socialElements.style.display = "";

    document.body.style.overflow = ""; // Reset body overflow

    // Restore the scroll position to where it was before the lightbox opened
    const scrollPosition = sessionStorage.getItem("scrollPosition");
    if (scrollPosition) {
        window.scrollTo(0, parseInt(scrollPosition)); // Scroll to the stored position
    }
}

// Function to load media when lightbox is opened
function loadMedia(lightboxId) {
    const lightbox = document.getElementById(`Lightbox_${lightboxId}`);
    const modalContent = lightbox.querySelector(".modal-content");

    if (!modalContent) return;

    // Fetch media from the server if not cached
    const folderName = `lightbox_${lightboxId}`;
    console.log(`Fetching media for folder: ${folderName}`); // Log the folderName here as well
    fetchMediaData(folderName, lightboxId); // Fetch from server if not cached
}

// Function to fetch media data
function fetchMediaData(folderName, lightboxId, retries = 3) {
    console.log(`Fetching media for folder: ${folderName}`); // Log the folderName being passed

    // Check if the media for this lightbox is already present in the DOM
    const existingMedia = document.querySelector(`#Lightbox_${lightboxId} .image-slide`);

    if (existingMedia) {
        // Media already present in the DOM, so no need to fetch again
        console.log("Media already present in the DOM, skipping fetch.");
        return; // No need to fetch again
    }

    // If media is not present in the DOM, fetch it from the server
    fetch(`https://new-vhym.onrender.com/api/get-cloudinary-media?folder=${folderName}`)
        .then((response) => response.json())
        .then((mediaFiles) => {
            console.log("Fetched media files:", mediaFiles);

            if (mediaFiles.length > 0) {
                // Insert the fetched media into the DOM
                displayMediaFiles(mediaFiles, lightboxId, folderName);
            }
        })
        .catch((err) => {
            console.error("Error loading media:", err);
            if (retries > 0) {
                console.log(`Retrying... Remaining retries: ${retries}`);
                setTimeout(() => fetchMediaData(folderName, lightboxId, retries - 1), 2000);
            } else {
                alert(`Error loading media for Lightbox ${lightboxId}: ${err.message}`);
            }
        });
}

// Function to display fetched media in the lightbox
function displayMediaFiles(mediaFiles, lightboxId, folderName) {
    console.log("lightboxId value: ", lightboxId); // Log the lightboxId value to inspect it
    console.log("folderName value: ", folderName); // Log folderName to check if it's undefined

    const lightbox = document.getElementById(`Lightbox_${lightboxId}`);
    const modalContent = lightbox.querySelector(".modal-content");

    if (!modalContent) return;

    // Make sure folderName is defined and can be split
    if (folderName) {
        mediaFiles.forEach((media, index) => {
            console.log(`Inserting media for ${folderName}: ${media.src}`);

            // Sanitize the alt value to make it a valid ID for CSS selector
            const sanitizedAlt = media.alt.replace(/\//g, '_').replace(/[^a-zA-Z0-9_-]/g, '');

            // Avoid inserting the same media again by checking if it's already in the DOM
            if (!document.querySelector(`#media-${sanitizedAlt}`)) {
                console.log(`Inserting image with src: ${media.src}`);

                // Create an image element
                const mediaElement = document.createElement('img');
                mediaElement.src = media.src;
                mediaElement.alt = media.alt;
                mediaElement.classList.add("image-slide"); // Add "image-slide" class

                // Set the width and height to 100% to make it fill the container
                mediaElement.style.width = "100%";
                mediaElement.style.height = "100%";

                // Ensure folderName is valid before using split
                const lightboxNumber = folderName.split('_')[1]; // Extract the number part of the folder name (e.g., '15' from 'lightbox_15')
                const slideClass = `slide${lightboxNumber}`; // Use slideX as the class name
                const slide = document.createElement('div');

                slide.classList.add('slide');
                slide.classList.add(slideClass);
                slide.appendChild(mediaElement);

                // Set an ID for the media element to avoid duplicate insertion
                mediaElement.id = `media-${sanitizedAlt}`;

                // Append the slide to the modal-content
                modalContent.appendChild(slide);
                console.log(`Added image: ${media.src}`);

                // Make sure the first slide is active, and others are hidden
                const allSlides = modalContent.querySelectorAll('.slide'); // Get all slide divs
                allSlides.forEach((el, idx) => {
                    el.style.display = idx === 0 ? "flex" : "none"; // Display only the first slide initially
                    el.classList.remove('active-slide', 'next-slide', 'previous-slide'); // Remove previous classes
                });

                // Add the appropriate classes to the first slide
                if (allSlides.length > 0) {
                    allSlides[0].classList.add('active-slide');
                }
            } else {
                console.log(`Media already exists in the DOM: ${media.src}`);
            }
        });
    } else {
        console.error("folderName is undefined or invalid!");
    }
}



// Function to store the last viewed slide
function storeLastSlide(lightboxId, slideIndex) {
    sessionStorage.setItem(`lastSlide_${lightboxId}`, slideIndex); // Store the slide index in sessionStorage
}

// Function to change slides
function toSlide(lightboxId, slideIndex) {
    showSlide(lightboxId, slideIndex);
    storeLastSlide(lightboxId, slideIndex);
}

// Function to change slides
function changeSlide(NR, n) {
    slideIndex += n;
    const slides = document.getElementsByClassName(`slide${NR}`);

    if (slideIndex < 1) {
        slideIndex = slides.length;
    } else if (slideIndex > slides.length) {
        slideIndex = 1;
    }

    showSlide(NR, slideIndex);
    document.dispatchEvent(new Event("slideChange"));
}

// Function to show a specific slide
function showSlide(slideGroup, e) {
    const slides = document.getElementsByClassName(`slide${slideGroup}`);
    if (e > slides.length) slideIndex = 1;
    else if (e < 1) slideIndex = slides.length;
    else slideIndex = e;

    for (let n = 0; n < slides.length; n++) {
        slides[n].style.display = "none";
        slides[n].classList.remove("active-slide", "previous-slide", "next-slide");
    }

    if (slides.length === 1) {
        slides[0].style.display = "flex";
        slides[0].classList.add("active-slide");
    } else {
        if (slides[slideIndex - 1]) {
            slides[slideIndex - 1].style.display = "flex";
            slides[slideIndex - 1].classList.add("active-slide");
        }

        const prevIndex = slideIndex - 2 >= 0 ? slideIndex - 2 : slides.length - 1;
        if (slides[prevIndex]) {
            slides[prevIndex].style.display = "flex";
            slides[prevIndex].classList.add("previous-slide");
        }

        const nextIndex = slideIndex < slides.length ? slideIndex : 0;
        if (slides[nextIndex]) {
            slides[nextIndex].style.display = "flex";
            slides[nextIndex].classList.add("next-slide");
        }
    }

    storeLastSlide(slideGroup, slideIndex);
}

// Function to set up key events for navigation
function setKeys(lightboxId) {
    window.onkeydown = function(e) {
        const key = e.key || e.code;

        if (key === "Escape") {
            closeLightbox(lightboxId);
        } else if (key === "ArrowRight") {
            changeSlide(lightboxId, 1);
        } else if (key === "ArrowLeft") {
            changeSlide(lightboxId, -1);
        }
    };
}

// Initialize pointer interaction
function setupPointer() {
    const Xmax = getHighestLightboxNumber();
    const pointerElement = document.getElementById("before-pointer");

    pointerElement.onclick = function() {
        openLightbox(Xmax);
        showSlide(Xmax, 1);
    };
}

// Function to get the highest lightbox number
function getHighestLightboxNumber() {
    const lightboxes = document.querySelectorAll('[id^="Lightbox_"]');
    let highest = 0;
    lightboxes.forEach((lightbox) => {
        const id = lightbox.id;
        const number = parseInt(id.replace("Lightbox_", ""));
        if (number > highest) highest = number;
    });
    return highest;
}

window.onload = setupPointer;


// THIS PART IS INDEX

// Define media query to check screen width
var sizer = window.matchMedia("(min-width: 950px)");

// Get all elements with the class "figure.project-index"
const collection = document.getElementsByClassName("figure.project-index");

// Get the number of "project-index" elements (could be useful later)
let numb = collection.length;

// Event listener for mouseenter on the mouseTarget element
mouseTarget.addEventListener("mouseenter", function() {
    // If the screen width is greater than or equal to 950px
    if (sizer.matches) {
        // Change the background color of the body to a random color from --randomcolor2
        document.getElementById("bodyid").style.background = "var(--randomcolor2)";

        // Loop through all project-index elements and set their border to a random color
        for (let e = 0; e < collection.length; e++) {
            collection[e].style.border = "solid 2px var(--randomcolor2)";
        }
    } else {
        // If the screen width is less than 950px, reset the body background color
        document.getElementById("bodyid").style.background = "";

        // Set the border color for all project-index elements
        for (let t = 0; t < collection.length; t++) {
            collection[t].style.border = "solid 2px var(--randomcolor2)";
        }
    }
});

// Event listener for mouseleave on the mouseTarget element
mouseTarget.addEventListener("mouseleave", function() {
    // If the screen width is greater than or equal to 950px
    if (sizer.matches) {
        // Reset the background color of the body
        document.getElementById("bodyid").style.background = "";

        // Reset the border color for all project-index elements
        for (let e = 0; e < collection.length; e++) {
            collection[e].style.border = "solid 2px var(--randomcolor2)";
        }
    } else {
        // If the screen width is less than 950px, reset the background color
        document.getElementById("bodyid").style.background = "";

        // Reset the border color for all project-index elements
        for (let t = 0; t < collection.length; t++) {
            collection[t].style.border = "solid 2px var(--randomcolor2)";
        }
    }
});

// Function to change the value of the CSS variable --randomcolor
function changeColor() {
    // Define an array of allowed colors
    const colors = ["yellow", "blue"];

    // Select a random color from the array
    const randomColor = colors[Math.floor(Math.random() * colors.length)];

    // Set the selected color to the --randomcolor CSS variable
    document.documentElement.style.setProperty("--randomcolor", randomColor);
}

// Change the color immediately and then every 5 seconds
changeColor();
setInterval(changeColor, 5000);

